SINA_SMART["histo1-git"] = {"lecture":"histo1-git","title":"Histology of the digestive system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-git:e0","text":"Four layers: mucosa, submucosa, muscularis externa, serosa/adventitia.","topic":"The general plan","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e1","text":"Mucosa = epithelium + lamina propria (MALT) + muscularis mucosae.","topic":"The general plan","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e2","text":"Submucosal (Meissner) and myenteric (Auerbach) plexuses.","topic":"The general plan","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e3","text":"Oesophagus: non-keratinised stratified squamous; adventitia.","topic":"Tongue, oesophagus and stomach","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e4","text":"Stomach: rugae, gastric pits; parietal (HCl, IF), chief (pepsinogen) cells.","topic":"Tongue, oesophagus and stomach","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e5","text":"Small intestine: plicae, villi with lacteal, microvilli, crypts with Paneth cells.","topic":"Small intestine","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e6","text":"Brunner's glands: duodenal submucosa; Peyer's patches: ileum.","topic":"Small intestine","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e7","text":"Large intestine: no villi, many goblet cells, teniae coli, haustra.","topic":"Large intestine, appendix and glands","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-git:e8","text":"Pancreas: exocrine acini + endocrine islets of Langerhans.","topic":"Large intestine, appendix and glands","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"k660us":"a","132p1vx":"a","dti6l3":"a","1lu2sg1":"a","52nys4":"a","1swkd3l":"a","1fdrbjw":"a","1dcmz2i":"a","1vqejmu":"a","mkhvy4":"a","1bblkyd":"a","hsg3xf":"a","5h367s":"a","jozwna":"a","1gmb7yz":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-git:e0":{"s":0,"u":["Four layers: mucosa, submucosa, muscularis externa, serosa/adventitia.","Serosa (mesothelium on loose CT) where the gut is in the peritoneal cavity, adventitia where it is not.","From the oesophagus to the anal canal the wall has the same four layers ."],"dp":[]},"histo1-git:e1":{"s":0,"u":["Mucosa = epithelium + lamina propria (MALT) + muscularis mucosae.","Mucosa : lining epithelium (absorbs nutrients, secretes mucus, continuous with intrinsic glands), lamina propria (loose CT with capillaries and most of the mucosa-associated lymphoid tissue, MALT) and muscularis mucosae (thin muscle for local movements)."],"dp":[]},"histo1-git:e2":{"s":0,"u":["Submucosal (Meissner) and myenteric (Auerbach) plexuses.","The enteric nervous system , with about 100 million neurons, has a submucosal (Meissner) plexus and a myenteric (Auerbach) plexus ; parasympathetic input stimulates digestion, sympathetic input inhibits it."],"dp":[]},"histo1-git:e3":{"s":1,"u":["Oesophagus: non-keratinised stratified squamous; adventitia.","Oesophagus : non-keratinised stratified squamous epithelium, submucosal mucous glands, muscularis externa and an adventitia .","Tongue : a mass of striated muscle in three planes covered by stratified squamous mucosa, with papillae on the dorsum and taste buds opening at taste pores."],"dp":[]},"histo1-git:e4":{"s":1,"u":["Stomach: rugae, gastric pits; parietal (HCl, IF), chief (pepsinogen) cells.","Surface simple columnar mucous epithelium dips into gastric pits , into which glands open: short tubular cardiac glands ; in the fundus and body, long glands with parietal cells (HCl, intrinsic factor), chief cells (pepsinogen) and mucous neck cells; deep pits and coiled mucous glands in the pylorus.","Stomach : the undistended mucosa and submucosa form longitudinal folds, rugae ."],"dp":[]},"histo1-git:e5":{"s":2,"u":["Small intestine: plicae, villi with lacteal, microvilli, crypts with Paneth cells.","Between villi, crypts of Lieberkühn contain columnar cells, goblet cells, stem cells , Paneth cells (antimicrobial) and enteroendocrine (argentaffin) cells.","Surface amplification: length, plicae circulares (permanent submucosal folds, prominent in duodenum and jejunum, slowing food and increasing area), villi (tall columnar epithelium with a striated (brush) border , goblet cells, a core of capillaries and a central lacteal ) and microvilli ."],"dp":[{"h":"Coeliac disease: flattening the villi","t":"In coeliac disease an immune reaction to gluten damages the small intestinal mucosa. On biopsy the villi become short or flat , the crypts lengthen as stem cells try to compensate, and lymphocytes crowd the epithelium and lamina propria. Losing villi and microvilli removes most of the absorptive surface built by the four amplifications of this lecture, which is why patients develop diarrhoea, weight loss, iron and folate deficiency. With a gluten-free diet the villi grow back, because the crypt stem cells are spared. Source: the lecture's surface amplifications and crypt cells."}]},"histo1-git:e6":{"s":2,"u":["Brunner's glands: duodenal submucosa; Peyer's patches: ileum.","Peyer's patches are clusters of lymphoid follicles, typical of the ileum .","Brunner's glands in the duodenal submucosa secrete alkaline mucus that protects against gastric acid."],"dp":[]},"histo1-git:e7":{"s":3,"u":["Large intestine: no villi, many goblet cells, teniae coli, haustra.","Large intestine : simple columnar epithelium with a thin brush border and many goblet cells ; no plicae or villi ; straight crypts lined largely by goblet cells; Paneth cells usually absent; more prominent muscularis mucosae.","The outer longitudinal muscle forms three bands, the teniae coli ; the wall puckers into haustra , with fatty epiploic appendages ."],"dp":[]},"histo1-git:e8":{"s":3,"u":["Pancreas: exocrine acini + endocrine islets of Langerhans.","Pancreas : exocrine acini (grape-like clusters of serous cells) in lobules separated by septa, and endocrine islets of Langerhans (insulin, glucagon)."],"dp":[]}},"meta":{"k660us":{"a":"recall","vg":"histo1-git:e1/recall/1"},"132p1vx":{"a":"recall","vg":"histo1-git:e2/recall/1"},"dti6l3":{"a":"recall","vg":"histo1-git:e0/recall/1"},"1lu2sg1":{"a":"recall","vg":"histo1-git:e0/recall/2"},"52nys4":{"a":"recall","vg":"histo1-git:e3/recall/1"},"1swkd3l":{"a":"recall","vg":"histo1-git:e4/recall/1"},"1fdrbjw":{"a":"recall","vg":"histo1-git:e4/recall/2"},"1dcmz2i":{"a":"recall","vg":"histo1-git:e5/recall/1"},"1vqejmu":{"a":"recall","vg":"histo1-git:e5/recall/2"},"mkhvy4":{"a":"recall","vg":"histo1-git:e5/recall/3"},"1bblkyd":{"a":"recall","vg":"histo1-git:e6/recall/1"},"hsg3xf":{"a":"recall","vg":"histo1-git:e6/recall/2"},"5h367s":{"a":"recall","vg":"histo1-git:e7/recall/1"},"jozwna":{"a":"recall","vg":"histo1-git:e7/recall/2"},"1gmb7yz":{"a":"recall","vg":"histo1-git:e8/recall/1"}},"explRev":"15e97ffe9af2"};
